begin;
insert into public.ce_course2_resources(id,data) values
('course2_module9_pdf','{"base64": "", "sha256": "afe155d5b1c7f0cf9058f8200b710c63e176f92241eeafdb972e7db048497a33", "filename": "CE_HALO_Course2_Module09_LAST_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module9_questions','[{"module_id": "course_2_module_9", "question_id": "course_2_module_9_q01", "question_number": 1, "stem": "A patient reports tinnitus, metallic taste, and circumoral numbness 30 seconds into an ultrasound-guided interscalene ropivacaine injection. Which action is most appropriate?", "choice_a": "Stop injection immediately, call for help, and prepare for LAST response.", "choice_b": "Reposition the needle and reattempt injection.", "choice_c": "Administer additional sedation and complete the block.", "choice_d": "Slow the injection rate and continue with smaller aliquots.", "correct_choice": "a", "rationale": "Early prodromal symptoms of LAST — tinnitus, metallic taste, and circumoral numbness — require immediate cessation of local anesthetic administration and activation of the LAST response pathway. Continuing injection, adding sedation, or reattempting injection can worsen toxicity and delay rescue.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q02", "question_number": 2, "stem": "What is the recommended 20% lipid emulsion bolus for an adult weighing 55 kg with progressive LAST?", "choice_a": "3 mL/kg over 1 minute", "choice_b": "1.5 mL/kg over 2 to 3 minutes", "choice_c": "0.5 mL/kg over 5 minutes", "choice_d": "5 mL/kg over 10 minutes", "correct_choice": "b", "rationale": "For patients under 70 kg, ASRA 2020 recommends 20% lipid emulsion 1.5 mL/kg IV over 2 to 3 minutes as the initial bolus, followed by an infusion of 0.25 mL/kg/min.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q03", "question_number": 3, "stem": "Which local anesthetic is associated with the greatest cardiotoxic potential because of slow dissociation from cardiac sodium channels?", "choice_a": "Mepivacaine", "choice_b": "Chloroprocaine", "choice_c": "Bupivacaine", "choice_d": "Lidocaine", "correct_choice": "c", "rationale": "Bupivacaine is highly lipid soluble, strongly protein bound, and dissociates slowly from cardiac sodium channels, producing persistent conduction block and higher risk of refractory ventricular dysrhythmias.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q04", "question_number": 4, "stem": "A sedated 74-year-old with reduced ejection fraction develops QRS widening, bradycardia, and PEA minutes after a large-volume TAP block. Which action best fits ASRA 2020 guidance?", "choice_a": "Give 1 mg IV epinephrine and vasopressin per standard ACLS.", "choice_b": "Administer amiodarone plus lidocaine bolus for arrest.", "choice_c": "Withhold lipid emulsion until CNS symptoms are documented.", "choice_d": "Announce suspected LAST, start high-quality CPR, use small-dose epinephrine, and give 20% lipid emulsion.", "correct_choice": "d", "rationale": "LAST may present first with cardiovascular collapse in sedated patients. Modified ACLS calls for small-dose epinephrine (preferably < 1 mcg/kg), avoidance of vasopressin, and immediate 20% lipid emulsion. Absence of CNS prodrome does not exclude LAST.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q05", "question_number": 5, "stem": "Which medication should be avoided during LAST-related cardiac arrest?", "choice_a": "Vasopressin", "choice_b": "Sodium bicarbonate", "choice_c": "Amiodarone", "choice_d": "Epinephrine in small boluses", "correct_choice": "a", "rationale": "Vasopressin should be avoided in LAST resuscitation because it may worsen outcomes. Calcium channel blockers, beta-blockers, additional local anesthetics, and large epinephrine doses should also be avoided.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q06", "question_number": 6, "stem": "For treating LAST-related seizures, which medication class is preferred?", "choice_a": "Additional lidocaine", "choice_b": "Benzodiazepines", "choice_c": "Neuromuscular blockers alone", "choice_d": "Large-dose propofol", "correct_choice": "b", "rationale": "Benzodiazepines are preferred for seizure control. Large propofol doses can worsen hypotension and myocardial depression in unstable patients. Paralysis stops motor activity but does not treat cortical seizure activity, and additional local anesthetics are contraindicated.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q07", "question_number": 7, "stem": "Which physiologic derangement most directly worsens cardiac sodium channel binding and free-drug fraction during LAST?", "choice_a": "Hypothermia", "choice_b": "Alkalemia and hypocarbia", "choice_c": "Acidosis, hypoxemia, and hypercarbia", "choice_d": "Hypernatremia", "correct_choice": "c", "rationale": "Acidosis, hypoxemia, and hypercarbia increase the free (active) fraction of local anesthetic, enhance cardiac sodium channel binding, and worsen toxicity — which is why airway support, oxygenation, and ventilation are core LAST interventions.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q08", "question_number": 8, "stem": "What is the approximate upper limit for total 20% lipid emulsion administered in LAST resuscitation?", "choice_a": "3 mL/kg", "choice_b": "6 mL/kg", "choice_c": "25 mL/kg", "choice_d": "12 mL/kg", "correct_choice": "d", "rationale": "The ASRA 2020 checklist recommends not exceeding approximately 12 mL/kg total 20% lipid emulsion in LAST resuscitation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q09", "question_number": 9, "stem": "Which local anesthetic is most associated with methemoglobinemia in addition to LAST?", "choice_a": "Prilocaine and benzocaine", "choice_b": "Ropivacaine", "choice_c": "Bupivacaine", "choice_d": "Chloroprocaine", "correct_choice": "a", "rationale": "Prilocaine and benzocaine can cause methemoglobinemia, which may coexist with LAST. Clues include cyanosis, chocolate-brown blood, low pulse oximetry unresponsive to oxygen, and a saturation gap between SpO2 and PaO2.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q10", "question_number": 10, "stem": "Which factor most increases susceptibility to LAST by reducing protein binding and increasing free drug fraction?", "choice_a": "Renal transplantation", "choice_b": "Pregnancy, neonatal status, critical illness, and low-protein states", "choice_c": "Male sex", "choice_d": "High body mass index", "correct_choice": "b", "rationale": "Pregnancy, neonates, malnutrition, frailty, critical illness, acidosis, and low-protein states can reduce protein binding and increase the free (active) fraction of local anesthetic, raising LAST risk even at doses below the calculated maximum.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q11", "question_number": 11, "stem": "A patient develops confusion, tremor, and hypotension 4 hours after starting an IV lidocaine infusion in the PACU. What is the most appropriate first action?", "choice_a": "Increase the lidocaine infusion for better analgesia.", "choice_b": "Wait 60 minutes and reassess.", "choice_c": "Stop the infusion, support oxygenation and ventilation, obtain lipid emulsion, and treat as suspected delayed LAST.", "choice_d": "Attribute symptoms to opioids and administer naloxone.", "correct_choice": "c", "rationale": "Delayed LAST can occur from IV lidocaine infusion accumulation. The infusion should be stopped immediately, supportive care initiated, lipid emulsion obtained, and the presentation treated as suspected LAST while alternative causes are evaluated in parallel.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q12", "question_number": 12, "stem": "Which statement about ultrasound guidance in regional anesthesia is most accurate?", "choice_a": "Ultrasound guidance replaces the need for aspiration and incremental injection.", "choice_b": "Ultrasound guidance is only useful for deep blocks.", "choice_c": "Ultrasound guidance eliminates the risk of LAST.", "choice_d": "Ultrasound guidance improves needle-tip visualization and may reduce accidental vascular puncture but does not eliminate LAST risk.", "correct_choice": "d", "rationale": "Ultrasound guidance improves visualization and may reduce accidental intravascular injection, but it does not eliminate LAST. Aspiration, incremental injection, cumulative dose tracking, and rescue readiness remain essential.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q13", "question_number": 13, "stem": "During LAST resuscitation, which antiarrhythmic is preferred over lidocaine for ventricular dysrhythmias?", "choice_a": "Amiodarone", "choice_b": "Flecainide", "choice_c": "Procainamide", "choice_d": "Lidocaine bolus", "correct_choice": "a", "rationale": "Amiodarone is preferred over lidocaine because lidocaine is itself a local anesthetic and adding it can worsen sodium channel blockade and toxicity.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q14", "question_number": 14, "stem": "Which of the following best describes the recommended post-event monitoring after LAST-related cardiovascular instability?", "choice_a": "Monitored observation for 30 minutes.", "choice_b": "Monitored observation for at least 4 to 6 hours after cardiovascular instability, longer after cardiac arrest or ongoing infusion exposure.", "choice_c": "Discharge home immediately after symptom resolution.", "choice_d": "Admit for 7 days for lipid pharmacokinetics.", "correct_choice": "b", "rationale": "Recurrent LAST can occur after redistribution or continued absorption. Observation of at least 2 hours after seizure, 4–6 hours after cardiovascular instability, and longer after arrest, recurrent symptoms, high-dose exposure, or ongoing infusion is recommended.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q15", "question_number": 15, "stem": "Which of the following is a key modification of ACLS during LAST-related cardiac arrest?", "choice_a": "Full-dose epinephrine 1 mg IV every 3 to 5 minutes as standard.", "choice_b": "Add lidocaine infusion for antiarrhythmic support.", "choice_c": "Use small-dose epinephrine (preferably < 1 mcg/kg when possible).", "choice_d": "Substitute vasopressin for epinephrine.", "correct_choice": "c", "rationale": "Small-dose epinephrine (preferably < 1 mcg/kg) is recommended in LAST resuscitation because large doses may worsen dysrhythmias, impair gas exchange, and reduce the effectiveness of lipid rescue.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q16", "question_number": 16, "stem": "A CRNA is planning a bilateral erector spinae plane block in an 80-year-old, 55-kg patient with reduced ejection fraction. Which dosing approach is safest?", "choice_a": "Skip aspiration to save time in an elderly patient.", "choice_b": "Use the maximum weight-based dose to ensure block success.", "choice_c": "Combine bupivacaine and lidocaine at maximum doses for both.", "choice_d": "Use lower concentration, lower total milligram dose, incremental injection, and include surgeon infiltration in cumulative dose.", "correct_choice": "d", "rationale": "Older patients with cardiac disease and low body mass have reduced reserve and altered protein binding. Conservative dosing, lower concentration and total dose, incremental injection, and cumulative dose accounting across all sources are appropriate.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q17", "question_number": 17, "stem": "Which of the following features would MOST suggest high spinal anesthesia rather than LAST in a postpartum patient with sudden hypotension and bradycardia after neuraxial dosing?", "choice_a": "Rapidly ascending sensory and motor block, dyspnea, and difficulty speaking without CNS excitation.", "choice_b": "Progressive ventricular dysrhythmias with normal sensory block level.", "choice_c": "Perioral numbness followed by seizure.", "choice_d": "Metallic taste, tinnitus, and QRS widening.", "correct_choice": "a", "rationale": "High spinal anesthesia follows a neuraxial pattern with ascending block, weakness, dyspnea, and profound sympathectomy. Metallic taste, tinnitus, and QRS widening from sodium channel blockade point toward LAST.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q18", "question_number": 18, "stem": "Why should CRNAs treat maximum-dose tables as safety boundaries rather than dosing targets?", "choice_a": "Tables always underestimate safe doses.", "choice_b": "Tables do not account for injection-site vascularity, combined agents, infusion accumulation, or patient-specific vulnerability.", "choice_c": "Tables apply only to pediatric patients.", "choice_d": "Tables are copyrighted and cannot be relied upon.", "correct_choice": "b", "rationale": "Maximum-dose tables are useful upper boundaries but do not account for vascular injection sites, additive dosing across agents, infusion accumulation, pregnancy, cardiac or hepatic disease, or low muscle mass. Dose reduction may be appropriate even when calculated maximums have not been reached.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q19", "question_number": 19, "stem": "What is the most important handoff element when a patient leaves the OR with a continuous local anesthetic infusion?", "choice_a": "Only the infusion pump rate.", "choice_b": "No handoff is required if the infusion is at a low rate.", "choice_c": "Agent, concentration, route, bolus dose, infusion rate, start time, total dose, stop criteria, and location of lipid emulsion.", "choice_d": "The surgeon''s contact number only.", "correct_choice": "c", "rationale": "Comprehensive handoff — agent, concentration, route, bolus dose, infusion rate, start time, cumulative and maximum planned dose, stop criteria, and lipid emulsion location — is critical to prevent delayed LAST recognition.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q20", "question_number": 20, "stem": "A patient developed LAST during a fascial plane block, was stabilized after 20% lipid emulsion, and is now asymptomatic. Which action is appropriate?", "choice_a": "Immediately discharge home to reduce hospital costs.", "choice_b": "Restart the same local anesthetic infusion for analgesia.", "choice_c": "Order a repeat block to confirm safety.", "choice_d": "Maintain monitored observation, document dosing and response, communicate risk for recurrence, and debrief the team.", "correct_choice": "d", "rationale": "After stabilization, monitored observation, documentation, handoff about recurrence risk, and structured team debrief are essential. Local anesthetic infusions should not be restarted, and premature discharge is unsafe.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q21", "question_number": 21, "stem": "Which of the following is TRUE about liposomal bupivacaine and LAST risk?", "choice_a": "Cumulative bupivacaine exposure across liposomal and standard formulations should be considered additive; LAST is possible with concurrent or overlapping administration.", "choice_b": "Liposomal bupivacaine is exempt from cumulative dose communication.", "choice_c": "Liposomal bupivacaine should always be combined with standard bupivacaine at maximum dose.", "choice_d": "Liposomal bupivacaine cannot cause LAST because it is encapsulated.", "correct_choice": "a", "rationale": "Liposomal bupivacaine can produce LAST, especially when combined with other local anesthetics or given in large volumes to vascular sites. Bupivacaine exposure should be treated as additive across formulations, and product-specific separation intervals should be respected.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q22", "question_number": 22, "stem": "Which of the following is a system-level LAST prevention action?", "choice_a": "Requiring CRNAs to memorize doses without written reference.", "choice_b": "Maintaining a standardized LAST rescue kit and cognitive aid at every location where local anesthetics are administered, and running periodic simulation drills.", "choice_c": "Discouraging cumulative dose documentation.", "choice_d": "Removing lipid emulsion from block rooms to save refrigerator space.", "correct_choice": "b", "rationale": "System readiness — LAST rescue kits, immediately available 20% lipid emulsion, posted cognitive aids, structured handoffs, and regular simulation-based training — is a core prevention strategy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q23", "question_number": 23, "stem": "Which finding is MOST characteristic of intravascular epinephrine effect rather than early LAST?", "choice_a": "Progressive QRS widening and cardiovascular collapse.", "choice_b": "Persistent seizure activity.", "choice_c": "Brief hyperadrenergic tachycardia, hypertension, palpitations, and tremor that resolves quickly.", "choice_d": "Metallic taste, tinnitus, and circumoral numbness lasting hours.", "correct_choice": "c", "rationale": "Intravascular epinephrine effect is typically brief and hyperadrenergic (transient tachycardia, hypertension, palpitations, tremor). Persistent CNS or cardiovascular toxicity, especially with metallic taste, tinnitus, or QRS widening, points to LAST.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q24", "question_number": 24, "stem": "During a suspected LAST event, which of the following should be avoided?", "choice_a": "Amiodarone for ventricular dysrhythmias.", "choice_b": "Small-dose epinephrine.", "choice_c": "20% lipid emulsion.", "choice_d": "Additional local anesthetic administration.", "correct_choice": "d", "rationale": "Additional local anesthetic administration is contraindicated during suspected LAST because it can worsen sodium channel blockade and toxicity. Amiodarone, small-dose epinephrine, and 20% lipid emulsion are all appropriate.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_9", "question_id": "course_2_module_9_q25", "question_number": 25, "stem": "What is the CRNA''s most important role during the initial recognition phase of suspected LAST?", "choice_a": "Linking new neurologic or cardiovascular changes to recent local anesthetic exposure, stopping the local anesthetic, and activating the LAST response pathway.", "choice_b": "Waiting for laboratory confirmation of plasma local anesthetic levels.", "choice_c": "Documenting only after resolution.", "choice_d": "Continuing the block to preserve analgesia.", "correct_choice": "a", "rationale": "Recognition — linking new neurologic or cardiovascular changes to recent local anesthetic exposure — is the CRNA''s most important initial role. Local anesthetic must be stopped, the LAST response activated, and treatment begun without waiting for laboratory confirmation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course2_resources where id='course2_module9_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course2_catalog where id='1047241'),'Course must remain staged';
end $$;
commit;